import{_ as t,o,c as a,a3 as s}from"./chunks/framework.B02wg2PO.js";const m=JSON.parse('{"title":"Modes & Permissions","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/modes-and-permissions.md","filePath":"concepts/modes-and-permissions.md"}'),d={name:"concepts/modes-and-permissions.md"};function n(r,e,i,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="modes-permissions" tabindex="-1">Modes &amp; Permissions <a class="header-anchor" href="#modes-permissions" aria-label="Permalink to &quot;Modes &amp; Permissions&quot;">​</a></h1><p>Three independent dials control what an agent may do and how hard it thinks. They are easy to confuse, so this page separates them.</p><h2 id="_1-delegation-mode-—-ask-vs-work" tabindex="-1">1. Delegation mode — <code>ask</code> vs <code>work</code> <a class="header-anchor" href="#_1-delegation-mode-—-ask-vs-work" aria-label="Permalink to &quot;1. Delegation mode — `ask` vs `work`&quot;">​</a></h2><p>Set per delegation and per checklist task.</p><table tabindex="0"><thead><tr><th>Mode</th><th>Tool set</th><th>Writes</th><th>Typical use</th></tr></thead><tbody><tr><td><code>ask</code></td><td><code>Read</code>, <code>Grep</code>, <code>Glob</code></td><td>Never</td><td>Investigation, code reading, answering a question about a repo</td></tr><tr><td><code>work</code></td><td>Full (subject to agent permission)</td><td>Yes — commits, and opens a PR under <code>branch: new</code></td><td>Making the change</td></tr></tbody></table><p>An <code>ask</code> cannot become a <code>work</code> mid-flight. If an investigation concludes that a change is needed, that is a new task with <code>mode: &#39;work&#39;</code>, which is exactly the moment the approval gate should see it.</p><h2 id="_2-agent-permission-—-all-read-only-custom" tabindex="-1">2. Agent permission — <code>all</code> / <code>read-only</code> / <code>custom</code> <a class="header-anchor" href="#_2-agent-permission-—-all-read-only-custom" aria-label="Permalink to &quot;2. Agent permission — `all` / `read-only` / `custom`&quot;">​</a></h2><p>Set in <code>AGENT.md</code> frontmatter, or via Settings → Permissions. This is a property of the <em>agent</em>, not the delegation.</p><table tabindex="0"><thead><tr><th>Permission</th><th>Tools</th></tr></thead><tbody><tr><td><code>all</code></td><td>Every tool (default)</td></tr><tr><td><code>read-only</code></td><td>Exactly <code>[&#39;Read&#39;, &#39;Grep&#39;, &#39;Glob&#39;]</code></td></tr><tr><td><code>custom</code></td><td>Exactly the <code>tools:</code> allow-list</td></tr></tbody></table><p>Enforcement is two-layered: the SDK is constructed with the restricted tool set, and a <code>canUseTool</code> gate sits behind it. A <code>read-only</code> agent handed a <code>work</code> delegation is still read-only — the narrower of the two wins.</p><h2 id="_3-effort-mode" tabindex="-1">3. Effort mode <a class="header-anchor" href="#_3-effort-mode" aria-label="Permalink to &quot;3. Effort mode&quot;">​</a></h2><p>The reasoning tier for a call. It resolves most-specific-first:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>task.effort</span></span>\n<span class="line"><span>  → Run.agentConfigs[actor].effort</span></span>\n<span class="line"><span>    → Run.effortMode</span></span>\n<span class="line"><span>      → CustomAgent.effort</span></span>\n<span class="line"><span>        → global default (Settings)</span></span></code></pre></div><p>Per-task effort is what stops a plan from spending its heaviest tier on a file lookup and its cheapest on the hard implementation step. Spend enforcement may <strong>clamp</strong> the effort down when an allowance is running out, rather than refusing the call outright.</p><h2 id="project-policy-—-the-approval-gate" tabindex="-1">Project policy — the approval gate <a class="header-anchor" href="#project-policy-—-the-approval-gate" aria-label="Permalink to &quot;Project policy — the approval gate&quot;">​</a></h2><p>Separate from all three, and it governs <em>writes to a repo</em>. Declared in <code>memory/projects/&lt;name&gt;.md</code> frontmatter:</p><table tabindex="0"><thead><tr><th>Key</th><th>Values</th><th>Default</th></tr></thead><tbody><tr><td><code>branch</code></td><td><code>new</code> (cut <code>saidi/*</code> + PR) | <code>current</code> (commit on the checked-out branch)</td><td><code>new</code></td></tr><tr><td><code>approval</code></td><td><code>confirm</code> (ask before any write) | <code>auto</code> (proceed)</td><td><code>confirm</code></td></tr><tr><td><code>verify</code></td><td>Shell command run after a work delegation commits</td><td>none</td></tr></tbody></table><p>An unset, missing, or invalid value falls back to the built-in safe policy — <code>new</code> + <code>confirm</code> — unless the operator has changed the fallback in Settings → System. There is no permissive global default that silently applies.</p><h2 id="operator-permissions-multi-member-installs" tabindex="-1">Operator permissions (multi-member installs) <a class="header-anchor" href="#operator-permissions-multi-member-installs" aria-label="Permalink to &quot;Operator permissions (multi-member installs)&quot;">​</a></h2><p>Beyond the agent dials, org members carry permission keys that gate what <em>they</em> may do — including run steering and visibility:</p><table tabindex="0"><thead><tr><th>Key</th><th>Grants</th></tr></thead><tbody><tr><td><code>runs.steerAll</code></td><td>Steer any run, not just your own</td></tr><tr><td><code>runs.viewAll</code></td><td>See every run in the org</td></tr></tbody></table><p>A run&#39;s owner can always steer it; a member it was <code>sharedWith</code> can watch the thread but not steer. Every turn and delegation in a run resolves budgets, permissions, and connections against the run&#39;s <code>createdBy</code> member.</p><h2 id="choosing-sensibly" tabindex="-1">Choosing sensibly <a class="header-anchor" href="#choosing-sensibly" aria-label="Permalink to &quot;Choosing sensibly&quot;">​</a></h2><ul><li>Start every new repo at <code>approval: confirm</code> and <code>branch: new</code>. Move to <code>auto</code> only for repos where a bad commit is cheap to discard.</li><li>Give a custom agent <code>read-only</code> unless it demonstrably needs to write. <code>custom</code> with a short allow-list beats <code>all</code> for anything touching an external system.</li><li>Set <code>verify:</code> on every repo that has a test command. It is the cheapest way to make &quot;done&quot; mean something.</li></ul><p>See also: <a href="/docs/reference/project-policy">Project Policy</a> · <a href="/docs/guides/guardrails">Guardrails</a></p>',25)])])}const u=t(d,[["render",n]]);export{m as __pageData,u as default};
